class Solution {
  public long minCost(int n, int[][] cost) {
    long INF = Long.MAX_VALUE / 4;
    long[][] dp = new long[3][3];
    for (int a = 0; a < 3; a++)
      for (int b = 0; b < 3; b++) dp[a][b] = a == b ? INF : cost[0][a] + cost[n - 1][b];
    for (int i = 1; i < n / 2; i++) {
      long[][] nd = new long[3][3];
      for (int c = 0; c < 3; c++) {
        for (int d = 0; d < 3; d++) {
          nd[c][d] = INF;
          if (c == d) continue;
          long best = INF;
          for (int a = 0; a < 3; a++) {
            if (a == c) continue;
            for (int b = 0; b < 3; b++) {
              if (b != d) best = Math.min(best, dp[a][b]);
            }
          }
          nd[c][d] = best + cost[i][c] + cost[n - 1 - i][d];
        }
      }
      dp = nd;
    }
    long ans = INF;
    for (long[] row : dp) for (long v : row) ans = Math.min(ans, v);
    return ans;
  }
}
